"use client";

import * as React from "react";
import styles from "../styles/accordion-cards.module.css";

export interface AccordionCardsProps {
  /** Panel titles, left to right */
  items?: string[];
  /** One-line description per panel (shown when expanded) */
  descriptions?: string[];
  /** Initially expanded panel index */
  defaultIndex?: number;
  /** Controlled expanded panel index */
  index?: number;
  /** Called when the expanded panel changes */
  onIndexChange?: (index: number) => void;
  /** Expand on hover/focus, or only on click/Enter */
  expandOn?: "hover" | "click";
  /** Fill color of the expanded panel */
  accentColor?: string;
  /** Text color on the expanded panel */
  activeTextColor?: string;
  /** Height in pixels */
  height?: number;
  /** Gap between panels in pixels */
  gap?: number;
  /** How much wider the expanded panel grows */
  expandRatio?: number;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_ITEMS = ["Design", "Develop", "Deploy", "Scale"];
const DEFAULT_DESCRIPTIONS = ["Shape the idea into flows and screens.", "Build it with typed, tested components.", "Ship to the edge in one command.", "Grow without rewriting the foundation."];

export function AccordionCards({
  items = DEFAULT_ITEMS,
  descriptions = DEFAULT_DESCRIPTIONS,
  defaultIndex = 0,
  index,
  onIndexChange,
  expandOn = "hover",
  accentColor = "#ff8a1f",
  activeTextColor = "#140b02",
  height = 260,
  gap = 10,
  expandRatio = 3.2,
  className = "",
  style,
}: AccordionCardsProps) {
  const list = items.length ? items : DEFAULT_ITEMS;
  const [indexState, setIndexState] = React.useState(Math.min(Math.max(defaultIndex, 0), list.length - 1));
  const active = index ?? indexState;
  const buttons = React.useRef<(HTMLButtonElement | null)[]>([]);
  const baseId = React.useId();

  const activate = (i: number) => {
    if (i === active) return;
    if (index === undefined) setIndexState(i);
    onIndexChange?.(i);
  };

  const onKeyDown = (e: React.KeyboardEvent, i: number) => {
    const map: Record<string, number> = { ArrowRight: i + 1, ArrowDown: i + 1, ArrowLeft: i - 1, ArrowUp: i - 1, Home: 0, End: list.length - 1 };
    if (!(e.key in map)) return;
    e.preventDefault();
    const next = (map[e.key] + list.length) % list.length;
    buttons.current[next]?.focus();
    activate(next);
  };

  return (
    <div
      role="group"
      aria-label="Expandable panels"
      className={`${styles.root} ${className}`.trim()}
      style={
        {
          "--mf-ac-height": `${height}px`,
          "--mf-ac-gap": `${gap}px`,
          "--mf-ac-accent": accentColor,
          "--mf-ac-on": activeTextColor,
          "--mf-ac-grow": expandRatio,
          ...style,
        } as React.CSSProperties
      }
    >
      {list.map((title, i) => {
        const isActive = i === active;
        const panelId = `${baseId}-panel-${i}`;
        return (
          <button
            key={`${title}-${i}`}
            ref={(el) => {
              buttons.current[i] = el;
            }}
            type="button"
            className={styles.panel}
            data-active={isActive || undefined}
            aria-expanded={isActive}
            aria-controls={panelId}
            onPointerEnter={() => expandOn === "hover" && activate(i)}
            onFocus={() => expandOn === "hover" && activate(i)}
            onClick={() => activate(i)}
            onKeyDown={(e) => onKeyDown(e, i)}
          >
            <span className={styles.index}>{String(i + 1).padStart(2, "0")}</span>
            <span id={panelId} className={styles.content} aria-hidden={!isActive}>
              <span className={styles.title}>{title}</span>
              {descriptions[i] && <span className={styles.description}>{descriptions[i]}</span>}
            </span>
            {!isActive && <span className={styles.srOnly}>{title}</span>}
          </button>
        );
      })}
    </div>
  );
}

.root {
  display: flex;
  gap: var(--mf-ac-gap, 10px);
  width: 100%;
  max-width: 44rem;
  height: var(--mf-ac-height, 260px);
  color: var(--mf-fg, #f4f4f6);
}

.panel {
  position: relative;
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  justify-content: space-between;
  min-width: 0;
  padding: 1.25rem;
  overflow: hidden;
  border: 1px solid var(--mf-border, #2e2e38);
  border-radius: 1rem;
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    flex-grow 520ms cubic-bezier(0.22, 1, 0.36, 1),
    background-color 320ms ease,
    border-color 320ms ease,
    color 320ms ease;
}

.panel:hover {
  border-color: var(--mf-border-strong, #52525b);
}

.panel[data-active] {
  flex-grow: var(--mf-ac-grow, 3.2);
  border-color: var(--mf-ac-accent, #ff8a1f);
  background-color: var(--mf-ac-accent, #ff8a1f);
  color: var(--mf-ac-on, #140b02);
}

.panel:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 3px;
}

.index {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.875rem;
  opacity: 0.85;
}

.content {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  /* Fixed minimum so text doesn't reflow while the panel grows; the description wraps within it. */
  min-width: min(13rem, 100%);
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 260ms ease, transform 420ms cubic-bezier(0.22, 1, 0.36, 1);
}

.panel[data-active] .content {
  opacity: 1;
  transform: none;
  transition-delay: 140ms;
}

.title {
  white-space: nowrap;
  font-size: 1.625rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.description {
  max-width: 16rem;
  font-size: 0.875rem;
  line-height: 1.4;
  opacity: 0.8;
  white-space: normal;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .panel,
  .content {
    transition: none;
  }
}

