"use client";

import { useState } from "react";

const items = ["Design", "Develop", "Deploy", "Scale"];

export function AccordionCardsTailwind() {
  const [active, setActive] = useState(0);
  return (
    <div className="flex h-64 w-full max-w-2xl gap-2.5">
      {items.map((title, i) => (
        <button
          key={title}
          onPointerEnter={() => setActive(i)}
          onFocus={() => setActive(i)}
          aria-expanded={active === i}
          className={`flex min-w-0 flex-col justify-between overflow-hidden rounded-2xl border p-5 text-left transition-all duration-500 ${active === i ? "flex-[3.2] border-orange-500 bg-orange-500 text-orange-950" : "flex-1 border-zinc-800 bg-zinc-900 text-zinc-100"}`}
        >
          <span className="font-mono text-sm">{String(i + 1).padStart(2, "0")}</span>
          <span className={`text-2xl font-bold transition-opacity ${active === i ? "opacity-100" : "opacity-0"}`}>{title}</span>
        </button>
      ))}
    </div>
  );
}
